documents.earlier_later:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
base: SRC
input: {SRC: {path: source.csv, types: {ID: int, VAL: int}}, DONOR: {path: donor.csv, types: {KEY: int}}}
output: {path: out.csv, columns: [ID, VALUE]}
intermediates:
  - id: EARLIER
    dataset: SRC
    key: {ID: DONOR.NEWKEY}
  - id: LATER
    dataset: DONOR
    key: {KEY: ID}
    derivations:
      NEWKEY: KEY
      LOOKED_UP: EARLIER.VAL
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: LATER.LOOKED_UP}

