documents.last_dose:
yamaa: "1.0"
type: spec
domain: ADPC
keys: [USUBJID, PCSEQ]
base: PC
input:
  PC: {path: pc.csv, types: {PCSEQ: int, PCDTC: datetime}}
  EX: {path: ex.csv, types: {EXSTDTC: datetime}}
  DM: dm.csv
intermediates:
  - id: LAST_DOSE
    dataset: EX
    key: [USUBJID]
    between: {value: ADTM, lower: EXSTDTC}
    order_by: [EX.EXSTDTC]
    keep: last
  - id: SUBJ
    dataset: DM
    key: [USUBJID]
    derivations:
      SEXL: {str_case: {source: SEX, to: lower}}
columns:
  - {name: USUBJID, type: str, derivation: PC.USUBJID}
  - {name: PCSEQ, type: int, derivation: PC.PCSEQ}
  - {name: ADTM, type: datetime, derivation: PC.PCDTC}
  - {name: LDOSEDTM, type: datetime, derivation: LAST_DOSE.EXSTDTC}
  - {name: X, type: str, derivation: SUBJ.SEXL}
output: {path: out.csv, columns: [USUBJID, PCSEQ, ADTM, LDOSEDTM, X]}

