documents.qualified_range:
yamaa: "1.0"
type: spec
domain: OUT
input:
  SUBJ: {path: subj.csv, types: {SUBJDAY: int}}
  REF: {path: ref.csv, types: {REFDAY: int}}
  WIN: {path: win.csv, types: {LO: int, HI: int}}
  EVT: {path: evt.csv, key: [USUBJID], types: {EVDAY: int}}
keys: [USUBJID]
base: SUBJ
output: {path: out.csv, columns: [USUBJID, WINDOW]}
intermediates:
  - id: W
    dataset: WIN
    key: [USUBJID]
    between: {value: REF.REFDAY, lower: LO, upper: HI}
    order_by: [WIN.LO]
    keep: first
columns:
  - {name: USUBJID, type: str, derivation: SUBJ.USUBJID}
  - {name: WINDOW, type: str, derivation: W.NAME}

