input: {EX: ex.csv}
base: EX
output: {path: out.csv, columns: [USUBJID, SELECTED]}
intermediates:
  - id: DATES
    dataset: EX
    derivations:
      DATE: {to_date: {source: EXENDTC}}
    key: {DATE: EX.CHOICE}
