      DATE: {to_date: {source: EXSTDTC}}
      CHOICE: {first_available: {sources: [DATE], missing: 17}}
      SELECTED: DATES.DATE
columns:
  - {name: USUBJID, type: str, derivation: EX.USUBJID}
  - {name: SELECTED, type: date, derivation: RESULT.SELECTED}

